SELECT 'http_image_counts' AS label,
  (SELECT COUNT(*) FROM users WHERE avatar LIKE 'http%') AS users,
  (SELECT COUNT(*) FROM chats WHERE avatar LIKE 'http%') AS chats,
  (SELECT COUNT(*) FROM discover_items WHERE icon_url LIKE 'http%') AS discover_items,
  (SELECT COUNT(*) FROM discover_banners WHERE image_url LIKE 'http%') AS discover_banners,
  (SELECT COUNT(*) FROM topics WHERE cover_image LIKE 'http%') AS topics,
  (SELECT COUNT(*) FROM moments WHERE CAST(media_urls AS CHAR) LIKE '%http%') AS moments;

